def render(slug, data):
    file = ROOT/slug/'index.html'
    original = file.read_text()
    published = re.search(r'property="article:published_time" content="(\d{4}-\d{2}-\d{2})',original)
    published = published.group(1) if published else '2026-09-12'
    path = '/'+slug+'/'
    trail = [('Home','/'),('Services','/services/'),(data['h1'],path)]
    faqs = [(q,'<p>'+html.escape(a)+'</p>') for q,a in data['faqs']]
    body = page_header(h1=data['h1'],subtitle=data['intro'],trail=trail)
    body += '\n'.join(section(h,b) for h,b in data['sections'])
    body += faq_section(faqs)+related_section(data['links'])
    body += section('Sources and content updates', '<p>By AE Tax Advisors Team. Content updated October 1, 2026. '+link('/editorial-policy/','Read our editorial policy')+'.</p>'+bullets([link(url,label) for url,label in data['sources']])+'<p>General information; planning and filing decisions depend on your facts and the applicable tax-year rules. Examples are illustrative, not guaranteed outcomes.</p>')
    # Keep established contextual commercial paths so maintenance tests remain valid.
    for block in re.findall(r'<!-- commercial-owner-path -->.*?<!-- /commercial-owner-path -->',original,re.S):
        body += block
    schemas = [breadcrumb_schema(trail),faq_schema(faqs)]
    if data.get('article'):
        schemas += [article_schema(title=data['h1'],description=data['desc'],url=SITE+path,published=published,modified=DATE,citations=[u for u,l in data['sources']])]
    else:
        schemas += [{'@context':'https://schema.org','@type':'Service','@id':SITE+path+'#service','name':data['h1'],'url':SITE+path,'description':data['desc'],'provider':{'@type':'Organization','name':'AE Tax Advisors','url':SITE+'/'},'areaServed':{'@type':'Country','name':'United States'}}]
    if data.get('local'):
        schemas += [{'@context':'https://schema.org','@type':'AccountingService','@id':SITE+'/#billings-office','name':'AE Tax Advisors','url':SITE+path,'telephone':'+1-631-614-5762','email':'team@aetaxadvisors.com','address':{'@type':'PostalAddress','streetAddress':'935 Lake Elmo Dr, Suite B','addressLocality':'Billings','addressRegion':'MT','postalCode':'59105','addressCountry':'US'}}]
    file.write_text(build_page(title=data['title'],description=data['desc'],path=path,body=body,schemas=schemas,published=published,modified=DATE,og_type='article' if data.get('article') else 'website'))

