def add_expansion(slug, heading, content):
    file=ROOT/slug/'index.html';source=file.read_text()
    block='<!-- service-search-expansion -->'+section(heading,content)+'<!-- /service-search-expansion -->'
    source=re.sub(r'<!-- service-search-expansion -->.*?<!-- /service-search-expansion -->','',source,flags=re.S)
    marker=source.find('<h2>Frequently Asked Questions</h2>')
    insertion=source.rfind('<section',0,marker) if marker>=0 else source.find('</main>')
    source=source[:insertion]+block+'\n'+source[insertion:]
    source=re.sub(r'(property="article:modified_time" content=")[^"]+',r'\g<1>'+DATE+'T00:00:00-06:00',source)
    source=re.sub(r'("dateModified"\s*:\s*")[^"]+',r'\g<1>'+DATE,source)
    file.write_text(source)

def contextual_paths():
    groups=[
      ('/short-term-rental-tax-strategy/','Plan the tax work for your short-term rental',['airbnb-tax-deductions','short-term-rental-tax-planning-basics','short-term-rental-tax-loophole-2026','cost-segregation-airbnb']),
      ('/physician-tax-planning/','Coordinate tax planning for your medical practice',['physician-cost-segregation','physician-retirement-planning','physician-exit-strategy','cost-segregation-for-medical-office']),
      ('/business-owner-tax-planning/','Build a tax plan for your business',['s-corp-vs-llc-tax-savings','s-corp-tax-strategy','year-end-tax-planning-checklist','accountable-plan']),
      ('/form-3115-cost-segregation/','Confirm the filing work for a depreciation lookback',['blog/form-3115-missed-depreciation','cost-segregation-cpa-coordination','amended-return-vs-form-3115'])
    ]
    count=0
    for target,heading,slugs in groups:
        for slug in slugs:
            file=ROOT/slug/'index.html'
            if not file.exists(): continue
            source=file.read_text()
            block='<!-- service-search-context -->'+section(heading,'<p>'+link(target,'Review the service, records and implementation scope')+' before committing to a strategy. Confirm what your advisor and return preparer each handle, then '+link('/discovery/','book a call')+' to discuss fit and next steps.</p>')+'<!-- /service-search-context -->'
            source=re.sub(r'<!-- service-search-context -->.*?<!-- /service-search-context -->','',source,flags=re.S)
            if '</main>' not in source:continue
            file.write_text(source.replace('</main>',block+'\n</main>',1));count+=1
    print('Contextual service links:',count)

def home_paths():
    file=ROOT/'index.html';source=file.read_text()
    block='<!-- service-search-home -->'+section('Find tax planning for your situation','<p>Start with the service that matches the next decision for your business or property.</p>'+bullets([
      link('/cost-segregation-study/','Rental property cost segregation')+' — study scope, fees and return coordination.',
      link('/short-term-rental-tax-strategy/','Airbnb and VRBO tax planning')+' — operational records, participation and depreciation.',
      link('/business-owner-tax-planning/','Business owner tax advisory')+' — entity choices, owner pay and implementation.',
      link('/physician-tax-planning/','Physician and medical practice planning')+' — business income, staff and property decisions.',
      link('/form-3115-cost-segregation/','Missed depreciation and lookback preparation')+' — correction procedure and filing scope.',
      link('/locations/billings/','Tax advisory in Billings, Montana')+' — headquarters, contact details and service fit.'
    ]))+'<!-- /service-search-home -->'
    source=re.sub(r'<!-- service-search-home -->.*?<!-- /service-search-home -->','',source,flags=re.S)
    file.write_text(source.replace('</main>',block+'\n</main>',1))

def main():
    for slug,data in PAGES.items():render(slug,data)
    for slug,(heading,content) in EXPANSIONS.items():add_expansion(slug,heading,content)
    contextual_paths();home_paths()
    for slug,description in {
        'cost-segregation-study': 'Nationwide cost segregation for rental properties, Airbnb, STRs and small multifamily. Compare study fees, scope, implementation and usable tax benefit.',
        'business-owner-tax-planning': 'Tax planning for business and practice owners. Coordinate entities, owner pay, retirement plans and major transactions with AE Tax Advisors.'
    }.items():
        file=ROOT/slug/'index.html';source=file.read_text()
        old=re.search(r'<meta name="description" content="([^"]+)"',source).group(1)
        source=source.replace(old,html.escape(description,quote=True))
        source=source.replace(html.unescape(old),description)
        file.write_text(source)
    print('Rebuilt',len(PAGES),'destinations; expanded',len(EXPANSIONS),'existing service pages; added homepage discovery paths.')

if __name__=='__main__':main()
